CREATE TABLE IF NOT EXISTS banking_financial_plans (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,name VARCHAR(128) NOT NULL,current_version BIGINT NOT NULL,settings_json JSON NOT NULL,status VARCHAR(16) NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,
 UNIQUE KEY uq_financial_owner(user_id,id),CONSTRAINT fk_financial_user FOREIGN KEY(user_id) REFERENCES banking_users(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS banking_replan_events (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,event_key VARCHAR(128) NOT NULL,request_hash CHAR(64) NOT NULL DEFAULT '',type VARCHAR(48) NOT NULL,resource_id VARCHAR(128) NOT NULL,reason VARCHAR(255) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'pending',attempts BIGINT NOT NULL DEFAULT 0,retry_at BIGINT NOT NULL DEFAULT 0,error_code VARCHAR(64) NOT NULL DEFAULT '',trace_id VARCHAR(128) NOT NULL DEFAULT '',task_id VARCHAR(128) NOT NULL DEFAULT '',created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,
 UNIQUE KEY uq_replan_key(user_id,event_key),UNIQUE KEY uq_replan_owner(user_id,id),KEY ix_replan_pending(status,retry_at,id),CONSTRAINT fk_replan_user FOREIGN KEY(user_id) REFERENCES banking_users(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS banking_plan_versions (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,version BIGINT NOT NULL,previous_version BIGINT NOT NULL,event_id BIGINT NULL,reason VARCHAR(255) NOT NULL,impact_minor BIGINT NOT NULL,data_digest CHAR(64) NOT NULL,needs_confirmation BOOLEAN NOT NULL,snapshot_json JSON NOT NULL,result_json JSON NOT NULL,trace_id VARCHAR(128) NOT NULL,task_id VARCHAR(128) NOT NULL,audit_id VARCHAR(36) NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,
 UNIQUE KEY uq_plan_owner(user_id,id),UNIQUE KEY uq_plan_version(plan_id,version),UNIQUE KEY uq_plan_event(plan_id,event_id),CONSTRAINT fk_version_plan FOREIGN KEY(user_id,plan_id) REFERENCES banking_financial_plans(user_id,id),CONSTRAINT fk_version_event FOREIGN KEY(user_id,event_id) REFERENCES banking_replan_events(user_id,id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS banking_plan_constraints (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,plan_version_id BIGINT NOT NULL,kind VARCHAR(32) NOT NULL,description VARCHAR(512) NOT NULL,amount_minor BIGINT NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,
 CONSTRAINT fk_constraint_version FOREIGN KEY(user_id,plan_version_id) REFERENCES banking_plan_versions(user_id,id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS banking_plan_decisions (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,plan_version_id BIGINT NOT NULL,`option` VARCHAR(16) NOT NULL,data_digest CHAR(64) NOT NULL,audit_id VARCHAR(36) NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,
 UNIQUE KEY uq_plan_decision(plan_version_id),CONSTRAINT fk_decision_plan FOREIGN KEY(user_id,plan_id) REFERENCES banking_financial_plans(user_id,id),CONSTRAINT fk_decision_version FOREIGN KEY(user_id,plan_version_id) REFERENCES banking_plan_versions(user_id,id)
) ENGINE=InnoDB;
DROP TRIGGER IF EXISTS qyj_replan_bank_accounts_insert;
CREATE TRIGGER qyj_replan_bank_accounts_insert AFTER INSERT ON banking_bank_accounts FOR EACH ROW INSERT INTO banking_replan_events(user_id,event_key,type,resource_id,reason,trace_id,task_id,created_at,updated_at) SELECT NEW.user_id,UUID(),'account_changed',CAST(NEW.id AS CHAR),'banking_bank_accounts:insert','','',CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED),CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED);
DROP TRIGGER IF EXISTS qyj_replan_bank_accounts_update;
CREATE TRIGGER qyj_replan_bank_accounts_update AFTER UPDATE ON banking_bank_accounts FOR EACH ROW INSERT INTO banking_replan_events(user_id,event_key,type,resource_id,reason,trace_id,task_id,created_at,updated_at) SELECT NEW.user_id,UUID(),'account_changed',CAST(NEW.id AS CHAR),'banking_bank_accounts:update','','',CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED),CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED) WHERE NOT(NEW.balance_minor <=> OLD.balance_minor) OR NOT(NEW.status <=> OLD.status);
DROP TRIGGER IF EXISTS qyj_replan_transactions_insert;
CREATE TRIGGER qyj_replan_transactions_insert AFTER INSERT ON banking_transactions FOR EACH ROW INSERT INTO banking_replan_events(user_id,event_key,type,resource_id,reason,trace_id,task_id,created_at,updated_at) SELECT NEW.user_id,UUID(),'transaction_added',CAST(NEW.id AS CHAR),'banking_transactions:insert',NEW.trace_id,NEW.task_id,CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED),CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED);
